<?php
namespace App\Controllers;
use App\Core\{Auth,View,Database,Request,Csrf,Response};use App\Services\{ProjectService,InvoiceService,TaskService};use App\Repositories\{ProjectRepository,InvoiceRepository};
final class ModuleController{
 public function leads():void{Auth::requireLogin();View::render('modules/leads',['leads'=>Database::pdo()->query('SELECT l.*,u.full_name assigned_name FROM leads l LEFT JOIN users u ON u.id=l.assigned_user_id ORDER BY l.id DESC')->fetchAll()]);}
 public function leadCreate():void{Auth::requireLogin();View::render('modules/lead_form');}
 public function leadStore():never{Auth::requireLogin();$r=new Request;if(!Csrf::check($r->input('_csrf'))){http_response_code(419);exit('CSRF');}Database::pdo()->prepare('INSERT INTO leads(tenant_id,name,email,phone,source,status,assigned_user_id,notes,created_at,updated_at) VALUES(1,?,?,?,?,?,?,?,NOW(),NOW())')->execute([$r->input('name'),$r->input('email'),$r->input('phone'),$r->input('source'),$r->input('status','new'),$r->input('assigned_user_id')?:Auth::id(),$r->input('notes')]);Response::redirect(route('leads'));}
 public function projects():void{Auth::requireLogin();View::render('modules/projects',['projects'=>(new ProjectRepository)->all(500)]);}
 public function projectCreate():void{Auth::requireLogin();View::render('modules/project_form',['clients'=>Database::pdo()->query('SELECT id,full_name FROM clients WHERE deleted_at IS NULL ORDER BY full_name')->fetchAll(),'services'=>Database::pdo()->query('SELECT id,name FROM services WHERE is_active=1 ORDER BY name')->fetchAll()]);}
 public function projectStore():never{Auth::requireLogin();$r=new Request;if(!Csrf::check($r->input('_csrf'))){http_response_code(419);exit('CSRF');}(new ProjectService)->create($r->all());Response::redirect(route('projects'));}
 public function projectView($id):void{Auth::requireLogin();$project=(new ProjectRepository)->findWithWorkflow((int)$id);if(!$project){http_response_code(404);exit('Project not found');}View::render('modules/project_view',['project'=>$project]);}
 public function projectEdit($id):void{Auth::requireLogin();View::render('modules/project_form',['project'=>(new ProjectRepository)->find((int)$id),'clients'=>Database::pdo()->query('SELECT id,full_name FROM clients WHERE deleted_at IS NULL ORDER BY full_name')->fetchAll(),'services'=>Database::pdo()->query('SELECT id,name FROM services WHERE is_active=1 ORDER BY name')->fetchAll()]);}
 public function projectUpdate($id):never{Auth::requireLogin();$r=new Request;if(!Csrf::check($r->input('_csrf'))){http_response_code(419);exit('CSRF');}(new ProjectService)->update((int)$id,$r->all());Response::redirect(route('project.view',['id'=>$id]));}
 public function projectStatus($id):never{Auth::requireLogin();$r=new Request;if(!Csrf::check($r->input('_csrf'))){http_response_code(419);exit('CSRF');}(new ProjectService)->setStatus((int)$id,(string)$r->input('status'));Response::redirect(route('project.view',['id'=>$id]));}
 public function workflowStepComplete($id):never{Auth::requireLogin();$r=new Request;if(!Csrf::check($r->input('_csrf'))){http_response_code(419);exit('CSRF');}(new \App\Services\WorkflowEngine)->advance((int)$id,Auth::id(),['manual'=>true]);Response::redirect($_SERVER['HTTP_REFERER']??route('projects'));}
 public function workflowComplete($id):never{Auth::requireLogin();$r=new Request;if(!Csrf::check($r->input('_csrf'))){http_response_code(419);exit('CSRF');}(new \App\Services\WorkflowEngine)->completeWorkflow((int)$id);Response::redirect($_SERVER['HTTP_REFERER']??route('projects'));}
 public function quotations():void{Auth::requireLogin();View::render('modules/quotations',['rows'=>Database::pdo()->query('SELECT q.*,c.full_name FROM quotations q JOIN clients c ON c.id=q.client_id ORDER BY q.id DESC')->fetchAll()]);}
 public function invoices():void{Auth::requireLogin();View::render('modules/invoices',['rows'=>(new InvoiceRepository)->all(500)]);}
 public function invoiceCreate():void{Auth::requireLogin();View::render('modules/invoice_form',['clients'=>Database::pdo()->query('SELECT id,full_name FROM clients WHERE deleted_at IS NULL ORDER BY full_name')->fetchAll(),'projects'=>Database::pdo()->query('SELECT id,name FROM projects ORDER BY id DESC')->fetchAll()]);}
 public function invoiceStore():never{Auth::requireLogin();$r=new Request;if(!Csrf::check($r->input('_csrf'))){http_response_code(419);exit('CSRF');}$desc=(array)$r->input('item_description',[]);$qty=(array)$r->input('item_quantity',[]);$price=(array)$r->input('item_price',[]);$items=[];foreach($desc as $i=>$v){if(trim((string)$v)==='')continue;$items[]=['description'=>$v,'quantity'=>(float)($qty[$i]??1),'unit_price'=>(float)($price[$i]??0)];}(new InvoiceService)->create($r->all(),$items);Response::redirect(route('invoices'));}
 public function invoiceView($id):void{Auth::requireLogin();$invoice=(new InvoiceRepository)->findWithItems((int)$id);if(!$invoice){http_response_code(404);exit('Invoice not found');}View::render('modules/invoice_view',['invoice'=>$invoice]);}
 public function invoicePayment($id):never{Auth::requireLogin();$r=new Request;if(!Csrf::check($r->input('_csrf'))){http_response_code(419);exit('CSRF');}(new InvoiceService)->recordPayment((int)$id,(float)$r->input('amount'),$r->input('payment_method','other'),$r->input('reference_no',''));Response::redirect(route('invoice.view',['id'=>$id]));}
 public function tasks():void{Auth::requireLogin();View::render('modules/tasks',['rows'=>Database::pdo()->query('SELECT t.*,c.full_name,u.full_name assigned_name FROM tasks t LEFT JOIN clients c ON c.id=t.client_id LEFT JOIN users u ON u.id=t.assigned_user_id ORDER BY COALESCE(t.due_at,"9999-12-31"),t.id DESC')->fetchAll()]);}
 public function taskCreate():void{Auth::requireLogin();View::render('modules/task_form',['clients'=>Database::pdo()->query('SELECT id,full_name FROM clients WHERE deleted_at IS NULL ORDER BY full_name')->fetchAll(),'projects'=>Database::pdo()->query('SELECT id,name FROM projects ORDER BY id DESC')->fetchAll(),'users'=>Database::pdo()->query('SELECT id,full_name FROM users WHERE is_active=1 AND is_banned=0 ORDER BY full_name')->fetchAll()]);}
 public function taskStore():never{Auth::requireLogin();$r=new Request;if(!Csrf::check($r->input('_csrf'))){http_response_code(419);exit('CSRF');}(new TaskService)->create($r->all());Response::redirect(route('tasks'));}
 public function taskComplete($id):never{Auth::requireLogin();(new TaskService)->complete((int)$id);Response::redirect(route('tasks'));}
 public function activities():void{Auth::requireLogin();$r=new Request;$perm=new \App\Services\PermissionService;$allowed=[];if($perm->can('Activity','view'))$allowed[]='stage_1';if($perm->can('Activity','security'))$allowed[]='stage_2';if($perm->can('Activity','changes'))$allowed[]='stage_3';if(!$allowed){http_response_code(403);exit('Forbidden');}$q=trim((string)$r->input('q',''));$stage=(string)$r->input('stage','');$where=['activity_stage IN ('.implode(',',array_fill(0,count($allowed),'?')).')'];$p=$allowed;if($q!==''){$where[]='(module_name LIKE ? OR action LIKE ? OR user_name LIKE ?)';$p=["%$q%","%$q%","%$q%"]; }if($stage!=='' && in_array($stage,$allowed,true)){$where[]='activity_stage=?';$p[]=$stage;}$sql='SELECT * FROM activity_logs WHERE '.implode(' AND ',$where).' ORDER BY id DESC LIMIT 300';$s=Database::pdo()->prepare($sql);$s->execute($p);View::render('modules/activities',['rows'=>$s->fetchAll(),'q'=>$q,'stage'=>$stage]);}
 public function notifications():void{Auth::requireLogin();$s=Database::pdo()->prepare('SELECT * FROM notifications WHERE user_id=? ORDER BY id DESC LIMIT 200');$s->execute([Auth::id()]);View::render('modules/notifications',['rows'=>$s->fetchAll()]);}
 public function documents():void{Auth::requireLogin();View::render('modules/documents',['rows'=>Database::pdo()->query('SELECT d.*,c.full_name FROM documents d LEFT JOIN clients c ON c.id=d.client_id ORDER BY d.id DESC LIMIT 300')->fetchAll()]);}
 public function communications():void{Auth::requireLogin();View::render('modules/communications',['rows'=>Database::pdo()->query('SELECT c.*,cl.full_name FROM communications c LEFT JOIN clients cl ON cl.id=c.client_id ORDER BY c.id DESC LIMIT 300')->fetchAll()]);}
 public function approvals():void{Auth::requireLogin();View::render('modules/approvals',['rows'=>Database::pdo()->query('SELECT a.*,c.full_name,s.name service_name,p.name project_name FROM approvals a LEFT JOIN clients c ON c.id=a.client_id LEFT JOIN services s ON s.id=a.service_id LEFT JOIN projects p ON p.id=a.project_id ORDER BY a.id DESC LIMIT 300')->fetchAll()]);}
 public function cases():void{Auth::requireLogin();View::render('modules/cases',['rows'=>Database::pdo()->query('SELECT ca.*,c.full_name FROM cases ca LEFT JOIN clients c ON c.id=ca.client_id ORDER BY ca.id DESC LIMIT 300')->fetchAll()]);}
}
